 const notes=field('Why this matters / description','textarea');const date=field('Target date','input','date');const priority=select('Priority',['Medium','High','Low']);const state=select('Status',['Active','Paused','Completed','Archived']);const method=select('Measurement',['Milestones','Numeric','Currency','Frequency','Qualitative']);const unit=field('Unit (e.g. books, USD, sessions per week)');const target=field('Target','input','number');target.min='0.000001';target.step='any';const current=field('Current value','input','number');current.min='0';current.step='any';const milestones=field('Milestones (one per line)','textarea');const reflection=field('Progress note (optional)','textarea');
 function toggle(){const m=method.value;for(const n of [unit,target,current])n.parentElement.hidden=!['Numeric','Currency','Frequency'].includes(m);target.required=!target.parentElement.hidden;current.required=target.required;milestones.parentElement.hidden=m!=='Milestones'}
 method.onchange=toggle;toggle();
 const actions=el('div',undefined,'actions');const save=el('button','Save goal');const cancel=button('Cancel edit',()=>reset());cancel.hidden=true;actions.append(save,cancel);form.append(actions);
