 form.onsubmit=run(async()=>{if(!title.value.trim())throw Error('Enter a goal title.');const old=editing;const ms=milestones.value.split('\n').map(x=>x.trim()).filter(Boolean).map(label=>({label,done:old?.milestones?.some(m=>m.label===label&&m.done)||false}));const data={type:'Goals',title:title.value.trim(),category:category.value.trim(),notes:notes.value,date:date.value,priority:priority.value,goalStatus:state.value,done:state.value==='Completed',method:method.value,unit:unit.value,target:Number(target.value||0),current:Number(current.value||0),milestones:ms};const entry={at:new Date().toISOString(),current:data.current,status:data.goalStatus,note:reflection.value};if(old){await updateDoc(doc(path(),old.id),{...data,history:arrayUnion(entry)})}else{await addDoc(path(),{...data,history:[entry],createdAt:serverTimestamp()})}reset()});
 function edit(r){editing=r;heading.textContent='Edit goal';cancel.hidden=false;title.value=r.title||'';category.value=r.category||'';notes.value=r.notes||'';date.value=r.date||'';priority.value=r.priority||'Medium';state.value=goalStatus(r);method.value=r.method||'Qualitative';unit.value=r.unit||'';target.value=r.target||'';current.value=r.current??0;milestones.value=(r.milestones||[]).map(m=>m.label).join('\n');reflection.value='';toggle();panel.scrollIntoView({behavior:'smooth'})}
 function draw(){list.replaceChildren();const visible=goals.filter(r=>(filter.value==='All'||goalStatus(r)===filter.value)&&(!catFilter.value||r.category===catFilter.value));if(!visible.length)list.append(el('p','No matching goals.'));for(const r of visible){const card=el('article',undefined,'record');const st=goalStatus(r);card.append(el('h3',r.title),el('p',[r.category,r.priority||'Medium',st,r.date?'Due '+r.date:''].filter(Boolean).join(' · ')),el('p',r.notes||''));const ms=r.milestones||[];let pct=null;if(r.method==='Milestones'&&ms.length)pct=100*ms.filter(m=>m.done).length/ms.length;else if(['Numeric','Currency','Frequency'].includes(r.method)&&r.target>0)pct=100*(r.current||0)/r.target;if(pct!==null){const bar=el('progress');bar.max=100;bar.value=Math.max(0,Math.min(100,pct));bar.setAttribute('aria-label','Goal progress');card.append(el('p',Math.round(pct)+'% · '+(r.method==='Milestones'?ms.filter(m=>m.done).length+' / '+ms.length:(r.current||0)+' / '+r.target+' '+(r.unit||''))),bar)}if(r.method==='Milestones')for(const [i,m] of ms.entries()){const label=el('label');label.style.display='block';const cb=el('input');cb.type='checkbox';cb.checked=m.done;cb.onchange=run(()=>updateDoc(doc(path(),r.id),{milestones:ms.map((x,j)=>j===i?{...x,done:cb.checked}:x),history:arrayUnion({at:new Date().toISOString(),note:(cb.checked?'Completed: ':'Reopened: ')+m.label})}));label.append(cb,document.createTextNode(' '+m.label));card.append(label)}
 const a=el('div',undefined,'actions');a.append(button('Edit / log progress',()=>edit(r)),button(st==='Completed'?'Reopen':'Complete',()=>{const next=st==='Completed'?'Active':'Completed';return updateDoc(doc(path(),r.id),{goalStatus:next,done:next==='Completed',history:arrayUnion({at:new Date().toISOString(),status:next})})}),button('Delete',()=>{if(confirm('Permanently delete this goal and its history?'))return deleteDoc(doc(path(),r.id))}));card.append(a);const related=records.filter(x=>x.goalId===r.id&&['Projects','Habits'].includes(x.type));if(related.length){const links=el('div');links.append(el('h4','Related actions'));for(const x of related){links.append(button(x.type+': '+x.title,()=>{page=x.type;render()}))}card.append(links)}const details=el('details');details.append(el('summary','Progress history'));for(const h of [...(r.history||[])].reverse())details.append(el('p',[new Date(h.at).toLocaleString(),h.status,h.current===undefined?'':'Value: '+h.current,h.note].filter(Boolean).join(' · ')));card.append(details);list.append(card)}}
