const title=field('Project name');title.required=true;const category=field('Category');const notes=field('Deliverable / description','textarea');const date=field('Deadline');date.type='date';const priority=select('Priority',['Medium','High','Low']);const state=select('Status',['Planned','In progress','On hold','Completed','Archived']);const goal=field('Related goal','select');goal.append(new Option('None',''));for(const g of goals)goal.append(new Option(g.title,g.id));
const tasks=field('Tasks (one per line; indent subtasks with two spaces)','textarea');
const a=el('div',undefined,'actions'),cancel=button('Cancel edit',()=>reset());cancel.hidden=true;a.append(el('button','Save project'),cancel);form.append(a);
