function edit(r){editing=r;heading.textContent='Edit project';cancel.hidden=false;title.value=r.title;category.value=r.category||'';notes.value=r.notes||'';date.value=r.date||'';priority.value=r.priority||'Medium';state.value=r.projectStatus||(r.done?'Completed':'Planned');goal.value=r.goalId||'';tasks.value=(r.tasks||[]).map(t=>(t.sub?'  ':'')+t.label).join('\n');panel.scrollIntoView({behavior:'smooth'})}
form.onsubmit=run(async()=>{if(!title.value.trim())throw Error('Enter a project name.');const old=editing;const used=new Set();const ts=tasks.value.split('\n').filter(x=>x.trim()).map(x=>{const label=x.trim(),sub=/^\s/.test(x);const i=(old?.tasks||[]).findIndex((t,j)=>!used.has(j)&&t.label===label&&!!t.sub===sub);if(i>=0)used.add(i);return {label,sub,done:i>=0?!!old.tasks[i].done:false}});const data={type:'Projects',title:title.value.trim(),category:category.value.trim(),notes:notes.value,date:date.value,priority:priority.value,projectStatus:state.value,done:state.value==='Completed',goalId:goal.value,tasks:ts};if(old)await updateDoc(doc(path(),old.id),data);else await addDoc(path(),{...data,createdAt:serverTimestamp()});reset()});
