function clearConnectedAccounts(){for(const c of Object.values(connectedAccounts)){c.lines=null;c.metrics=null;c.observedAt=null;if(c.auth)signOut(c.auth).catch(()=>{})}}
async function connectExternal(key){
const c=connectedAccounts[key],owner=user,token=epoch;if(!owner?.email||!owner.emailVerified)throw Error('Verify your Bigger Picture email first.');
try{
if(!c.auth){const a=initializeApp(c.config,'bp-connected-'+key);c.auth=initializeAuth(a,{persistence:inMemoryPersistence,popupRedirectResolver:browserPopupRedirectResolver});c.db=getFirestore(a)}
let u=c.auth.currentUser;if(!u){const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});u=(await signInWithPopup(c.auth,provider)).user}
if(epoch!==token||user?.uid!==owner.uid||!u.emailVerified||u.email?.toLowerCase()!==owner.email.toLowerCase())throw Error('Choose the same verified email as your Bigger Picture account.');
let lines;if(key==='spanish'){const [profile,words]=await Promise.all([getDoc(doc(c.db,'users',u.uid)),getDocs(collection(c.db,'users',u.uid,'vocabulary'))]);const completed=profile.data()?.completed;lines=[(Array.isArray(completed)?new Set(completed).size:0)+' lessons completed',words.size+' personal vocabulary words']}else{const snap=await getDocs(collection(c.db,'users',u.uid,'applications'));const jobs=snap.docs.map(d=>d.data()),applied=jobs.filter(j=>!!j.appliedDate&&j.status!=='Saved'&&j.status!=='Posting Closed');lines=[applied.length+' applications tracked',applied.filter(j=>j.status==='Interviewing').length+' currently interviewing',applied.filter(j=>j.status==='Offer').length+' current offers']}
if(epoch!==token||user?.uid!==owner.uid||c.auth.currentUser?.uid!==u.uid)throw Error('Account changed during connection.');c.lines=lines;c.metrics=key==='spanish'?{lessonsCompleted:Number(lines[0].split(' ')[0]),vocabularyWords:Number(lines[1].split(' ')[0])}:{applications:Number(lines[0].split(' ')[0]),interviewing:Number(lines[1].split(' ')[0]),offers:Number(lines[2].split(' ')[0])};c.observedAt=new Date().toISOString();render();
}catch(e){c.lines=null;if(c.auth)await signOut(c.auth).catch(()=>{});if(epoch===token)render();throw e}
}

const connectedMetricLabels={ducks:{lessonsCompleted:'Lessons completed',lessonsAssessed:'Lessons assessed'},music:{theoryLessons:'Theory lessons',instrumentLessons:'Instrument lessons',exercises:'Exercises'},spanish:{lessonsCompleted:'Lessons completed',vocabularyWords:'Vocabulary words'},jobs:{applications:'Applications',interviewing:'Currently interviewing',offers:'Current offers'}};
const connectedNames={ducks:'Ducks In Order',music:'Amélo',spanish:'Speaking Spanish',jobs:"Finder's Keepers"};
function collectBrowserMetrics(){const read=(k,array)=>{try{const x=JSON.parse(localStorage.getItem(k));return array?(Array.isArray(x)?x:null):(x&&typeof x==='object'&&!Array.isArray(x)?x:null)}catch{return null}};const d=read('ducks-in-order-progress-v4',false),m={};for(const [k,key] of [['theoryLessons','melodie-lessons'],['instrumentLessons','melodie-instrument-lessons'],['exercises','melodie-exercises']]){const a=read(key,true);if(a)m[k]=new Set(a).size}const out={};if(d)out.ducks={lessonsCompleted:Object.values(d).filter(x=>x?.completed===true).length,lessonsAssessed:Object.values(d).filter(x=>Number.isFinite(x?.score)).length};if(Object.keys(m).length)out.music=m;return out}
function cleanConnectedMetrics(source,metrics){return Object.fromEntries(Object.keys(connectedMetricLabels[source]||{}).filter(k=>Number.isSafeInteger(metrics?.[k])&&metrics[k]>=0).map(k=>[k,metrics[k]]))}
function reviewConnectedSnapshots(){return records.filter(r=>r.type==='ConnectedSnapshot'&&connectedNames[r.source]&&typeof r.observedAt==='string').map(r=>({source:r.source,observedAt:r.observedAt,metrics:cleanConnectedMetrics(r.source,r.metrics)})).filter(r=>Object.keys(r.metrics).length).sort((a,b)=>a.observedAt.localeCompare(b.observedAt))}
function renderSavedConnected(p){const section=el('section',undefined,'panel');section.append(el('h4','Saved cross-device progress'),el('p','Save aggregate totals to your private Bigger Picture account. Browser totals reflect this device only; they are not merged across devices. Saved totals are included in progress review exports.'));const snapshots=reviewConnectedSnapshots();for(const source of Object.keys(connectedNames)){const latest=snapshots.filter(r=>r.source===source).at(-1);const line=el('p',connectedNames[source]+': '+(latest?Object.entries(latest.metrics).map(([k,n])=>connectedMetricLabels[source][k]+' '+n).join(' · ')+' · Saved '+new Date(latest.observedAt).toLocaleString():'No saved snapshot'));section.append(line)}
const browser=collectBrowserMetrics();for(const source of Object.keys(connectedNames)){const c=connectedAccounts[source],metrics=cleanConnectedMetrics(source,browser[source]||c?.metrics);if(!Object.keys(metrics).length)continue;section.append(button('Save '+connectedNames[source]+' snapshot',async()=>{const observedAt=c?.observedAt||new Date().toISOString();await addDoc(path(),{type:'ConnectedSnapshot',source,observedAt,metrics,createdAt:serverTimestamp()});status('Saved '+connectedNames[source]+' progress.')}))}
section.append(button('Delete saved connected progress',async()=>{if(!confirm('Delete all saved connected progress snapshots? This does not change your other websites.'))return;const uid=user.uid;const items=records.filter(r=>r.type==='ConnectedSnapshot');for(let i=0;i<items.length;i+=400){const batch=writeBatch(db);for(const r of items.slice(i,i+400))batch.delete(doc(db,'users',uid,'records',r.id));await batch.commit()}}));p.append(section)}
